package com.voicetxt.reader;

import android.app.*;import android.content.*;import android.os.*;import android.view.View;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;

/** Real navigation and two-model handover; failures must not stop the old voice. */
public class InAppContinuousPlaybackTest extends VoiceWarmupTest {
 final AtomicReference<Activity> resumed=new AtomicReference<>();
 final Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){resumed.set(a);}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
 VoicePicker.Item pickerItem(MainActivity a,String key){VoicePackages.Selection selection=VoicePackages.get(a).resolve(key,"zh");if(selection!=null)a.readingPrefs.edit().putInt("pack_speaker_"+selection.pack.id+"_zh",selection.speaker).commit();for(VoicePicker.Item item:a.voicePicker.host.items())if(item.key.equals(key))return item;throw new AssertionError("Missing picker item "+key);}
 public void onStart(){Bundle result=new Bundle();SharedPreferences prefs=getTargetContext().getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(prefs.getAll());VoicePackages store=VoicePackages.get(getTargetContext());MainActivity reader=null;OfflineVoicesActivity manager=null;String fixtureId=UUID.randomUUID().toString();Application app=(Application)getTargetContext().getApplicationContext();boolean success=false;
  try{app.registerActivityLifecycleCallbacks(callbacks);prefs.edit().putString("readingLanguage","").commit();reader=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","continuous_app_qa").putExtra("book_name","应用内连续播放验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=reader;await(()->a.system!=null&&a.system.initialized,"System initialization",30000);
   SystemSpeaker.Option found=null;for(SystemSpeaker.Option voice:a.system.options)if(SystemSpeaker.offlineUsable(voice.voice)&&VoiceLanguages.matches("zh",voice.voice.getLocale())){found=voice;break;}check(found!=null,"Chinese system voice unavailable");final String systemKey=found.key;
   VoiceModel first=null,second=null;for(VoiceModel model:store.list("zh"))if(model.type.equals("kokoro")&&model.name.contains("int8")){first=model;break;}check(first!=null,"Need installed int8 Kokoro model");for(VoiceModel model:store.list("zh"))if(model.type.equals("vits")&&!model.id.equals(first.id)){second=model;break;}check(second!=null,"Need installed VITS model");final VoiceModel modelA=first,modelB=second;final String keyA=modelA.key(modelA.defaultSpeaker("zh")),keyB=modelB.key(modelB.defaultSpeaker("zh"));
   StringBuilder story=new StringBuilder("第一章 连续播放\n");for(int i=0;i<180;i++)story.append("我们沿着河边的小路慢慢前行，欣赏四周美丽的风景。\n");final String text=story.toString();ui(()->{a.stop();a.readingLanguage="";a.originalVoiceLanguage="zh";a.systemVoiceKey=systemKey;a.persistVoiceChoice(systemKey,"zh");a.text=text;a.chapters=MainActivity.parse(text);a.position=0;a.rate=1.8f;a.loopPlayback=false;a.showPosition(true);a.startReading();});await(()->a.playing&&a.latestHighlightEnd>0,"Initial speech did not start",20000);
   final int beforeBack=a.position;ui(a::onBackPressed);await(()->resumed.get() instanceof ShelfActivity&&!a.readerVisible,"Back did not show shelf",10000);final ShelfActivity shelf=(ShelfActivity)resumed.get();await(()->a.position>beforeBack,"Speech stopped after leaving reader",15000);ui(()->{PlaybackBubble.refresh();check(!a.destroyed&&!a.isFinishing()&&a.playing&&PlaybackService.reader()==a,"Reader was destroyed on Back");check(PlaybackBubble.instance.view!=null&&PlaybackBubble.instance.view.getVisibility()==View.VISIBLE,"Shelf mini player missing");PlaybackBubble.instance.view.performClick();});await(()->resumed.get()==a&&a.readerVisible,"Reader instance not reused",10000);
   int beforePopup=a.generation;ui(()->{a.chooseVoice();check(a.playing&&a.generation==beforePopup,"Opening voice chooser stopped speech");if(a.voicePicker.host.languages().contains("sv")){a.voicePicker.host.language("sv");a.voicePicker.refresh();check(a.playing&&a.voiceLanguage().equals("zh"),"Browsing another language changed active narration");a.voicePicker.host.language("zh");a.voicePicker.refresh();}a.voicePicker.host.select(pickerItem(a,keyA));check(a.playing&&a.systemVoiceKey.equals(systemKey)&&a.pendingVoiceChange!=null,"Native model selection interrupted old voice");a.voicePicker.dismiss();check(a.playing,"Closing chooser paused speech");});await(()->a.voiceChangesApplied>=1&&a.systemVoiceKey.equals(keyA),"System to native handover failed: "+a.latestStatus,40000);await(()->a.startupTiming!=null&&a.startupTiming.audioStartedAt>0&&a.offline instanceof PackageSpeaker,"Prepared native voice did not play",25000);ui(()->{check(((PackageSpeaker)a.offline).ready&&((PackageSpeaker)a.offline).loadCount==1,"Prepared native model reloaded");check(a.lastVoiceChangePosition>beforeBack,"Source position reset during handover");a.onBackPressed();});await(()->resumed.get() instanceof ShelfActivity&&!a.readerVisible,"Second Back failed",10000);
   manager=(OfflineVoicesActivity)startActivitySync(new Intent(getTargetContext(),OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity m=manager;await(()->m.system!=null&&m.system.initialized,"Manager system discovery",30000);final long beforeNative=a.voiceChangesApplied;ui(()->{m.select(new OfflineVoicesActivity.Item(modelB,"zh",modelB.defaultSpeaker("zh"),"QA"));check(a.playing,"Manager selection stopped active reading");});await(()->a.voiceChangesApplied>beforeNative&&a.systemVoiceKey.equals(keyB),"Native to native handover failed",45000);await(()->a.startupTiming.audioStartedAt>0,"Second native model did not play",25000);final int backgroundPosition=a.position;await(()->a.position>backgroundPosition,"Speech did not advance behind manager",20000);
   final long beforeSystem=a.voiceChangesApplied;ui(()->a.requestVoiceChange(systemKey,"zh"));await(()->a.voiceChangesApplied>beforeSystem&&a.systemVoiceKey.equals(systemKey),"Native to system handover failed",30000);check(a.playing,"Playback stopped on system handover");
   VoiceModel invalid=new VoiceModel();invalid.id=fixtureId;invalid.name="QA failed preload";invalid.type="vits";invalid.model="../outside.onnx";invalid.tokens="tokens.txt";invalid.languages.add("zh");invalid.speakers=1;invalid.sampleRate=22050;invalid.directory=getTargetContext().getCacheDir();synchronized(store){store.models.put(fixtureId,invalid);}final int beforeFailure=a.generation;ui(()->m.select(new OfflineVoicesActivity.Item(invalid,"zh",0,"QA")));await(()->a.pendingVoiceChange==null,"Failed preload did not finish",15000);ui(()->{check(a.playing&&a.systemVoiceKey.equals(systemKey)&&a.generation==beforeFailure,"Failed preload stopped/replaced active voice");check(prefs.getString("chineseVoiceKey","").equals(systemKey),"Failed preload persisted invalid choice");});await(()->!store.leases.containsKey(fixtureId),"Failed preload leaked lease",15000);synchronized(store){store.models.remove(fixtureId);}ui(()->{a.requestVoiceChange(keyA,"zh");a.requestVoiceChange(systemKey,"zh");check(a.playing&&a.pendingVoiceChange==null&&a.systemVoiceKey.equals(systemKey),"Cancelled/reselected voice interrupted playback");m.finish();});manager=null;await(()->resumed.get() instanceof ShelfActivity,"Return from manager failed",10000);final ShelfActivity currentShelf=(ShelfActivity)resumed.get();ui(()->{PlaybackBubble.refresh();a.stop(false);if(PlaybackService.active!=null)PlaybackService.active.parkPaused();check(!a.playing&&PlaybackService.reader()==a,"Mini-player pause lost reading session");a.startReading();});await(()->a.playing&&a.latestHighlightEnd>0,"Mini-player resume failed",15000);ui(()->PlaybackBubble.instance.view.performClick());await(()->resumed.get()==a&&a.readerVisible,"Mini-player did not reopen reader",10000);ui(()->{check(!a.destroyed&&a.position>0,"Reopening reset reading progress");a.stop();});
   result.putString("result","PASS: Back to shelf retains speech and live source progress; floating entry reopens same reader, playback pauses/resumes through its existing controls; browsing/closing voice chooser does not stop audio; system -> preloaded Kokoro -> different VITS -> system handovers while playing; failed preload keeps old voice and restores preferences; rapid reselect cancels stale preload; all user models retained");success=true;
  }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));}
  finally{if(manager!=null){final Activity activity=manager;ui(activity::finish);}if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}app.unregisterActivityLifecycleCallbacks(callbacks);synchronized(store){store.models.remove(fixtureId);}waitForIdleSync();restore(prefs,saved);getTargetContext().getSharedPreferences("reader_continuous_app_qa",0).edit().clear().commit();new File(getTargetContext().getFilesDir(),"book_continuous_app_qa.txt.position").delete();}
  finish(success?-1:0,result);
 }
}
